    __block NSUInteger calls=0,submits=0;NSData *image=PreviewImage();__block NSString *text=@"# Report\nTODO: explain units\n![diagram](image.png)\n";
    sheet.performCheck=^NSDictionary *(NSArray *paths,NSArray *ids,NSString *extra,NSMutableDictionary *cache,BOOL(^cancelled)(void),NSError **error){calls++;NSData *data=[text dataUsingEncoding:NSUTF8StringEncoding];NSDictionary *snapshot=@{@"paths":paths,@"files":@{@"report.md":@{@"text":text,@"data":data,@"version":AMPreflightHash(data),@"mode":@"100644"},@"image.png":@{@"image":@YES,@"data":image,@"version":AMPreflightHash(image)}},@"version":AMPreflightHash(data),@"head":@"synthetic",@"repository":course[@"fork"],@"branch":@"main"};NSString *requirements=[@"Explain the result.\n" stringByAppendingString:extra];return @{@"snapshot":snapshot,@"requirements":requirements,@"report":AMPreflightCheck(snapshot,requirements,cache,cancelled)};};sheet.submit=^(NSArray *paths,NSString *message){submits++;};
    [sheet.primary performClick:nil];Check([sheet.validation.stringValue containsString:@"选择"] && !calls,@"missing files and message explained without closing sheet");Check(sheet.checks[0].state==NSControlStateValueOff && sheet.checks[1].state==NSControlStateValueOff,@"no submission file preselected");sheet.message.stringValue=@"Synthetic revision";[sheet.checks[0] performClick:nil];[sheet.primary performClick:nil];Wait(^BOOL{return !sheet.checking && sheet.report!=nil;});Check(!sheet.checkPage.hidden && sheet.findings.count>0 && submits==0,@"real controls enter report without submitting");[sheet.primary performClick:nil];Check(!submits && [sheet.validation.stringValue containsString:@"核对"],@"quality acknowledgement required");
    [sheet backToFiles:nil];[sheet selectionChanged:nil];Check(sheet.checkPage.hidden && sheet.validation==sheet.filesValidation && [sheet.validation.stringValue containsString:@"1"],@"returning to files restores visible feedback and file selection");[sheet.filesPrimary performClick:nil];Wait(^BOOL{return !sheet.checking && sheet.report!=nil;});
