    Check(![sheet saveForExit] && !submits,@"update exit cannot silently submit checked assignment");text=@"# Report\nUpdated answer\n";sheet.acknowledge.state=NSControlStateValueOn;[sheet.primary performClick:nil];Wait(^BOOL{return !sheet.checking;});Check(!submits && sheet.acknowledge.state==NSControlStateValueOff && [sheet.validation.stringValue containsString:@"变化"],@"changed version returns to review instead of committing");sheet.acknowledge.state=NSControlStateValueOn;[sheet.primary performClick:nil];[sheet.primary performClick:nil];Wait(^BOOL{return submits==1;});Check(!sheet.window.sheetParent && calls>=4 && sheet.reviewSummary!=nil,@"one explicit final submit, with version and summary");NSUInteger finishedCalls=calls;[sheet save:nil];Check(sheet.closed && calls==finishedCalls && submits==1,@"closed submission ignores a second completed action");
